#!/usr/bin/env python3
"""Builds data/compounds/*.json (reference compounds) with molar masses computed from the element table.

Physical values are recalled general-chemistry reference values and are all marked unverified_reference.
The molar mass is derived from the formula with the element masses in build_elements.py.
Run from the project root after build_elements.py:  python3 tools/build_compounds.py
"""
import json
import re
import sys

sys.dont_write_bytecode = True
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "tools"))
import build_elements as E  # noqa: E402

SRC = "General-chemistry reference values recalled from memory; check a supplier data sheet or handbook before teaching use."
SUB = str.maketrans("0123456789", "₀₁₂₃₄₅₆₇₈₉")


def display(formula):
    """CuSO4.5H2O -> CuSO₄·5H₂O (digits after a letter or bracket become subscripts)."""
    parts = []
    for part in formula.split("."):
        m = re.match(r"^(\d+)(.*)$", part)
        lead, body = (m.group(1), m.group(2)) if m else ("", part)
        parts.append(lead + re.sub(r"(?<=[A-Za-z\)])(\d+)", lambda x: x.group(1).translate(SUB), body))
    return "·".join(parts)


def v(value, unit, note=None):
    if value is None:
        return None
    out = {"value": value, "unit": unit, "status": "unverified_reference", "source": SRC}
    if note:
        out["note"] = note
    return out


