def main():
    out_dir = ROOT / "data/compounds"
    out_dir.mkdir(parents=True, exist_ok=True)
    for old in out_dir.glob("*.json"):
        old.unlink()
    for (cid, name, formula, comp, state, look, color, solution_color, density, mp, bp, solubility, solubility_note,
         hazards, hazard_text, storage, roles, notes, sim) in C:
        mass = round(sum(E.MASS[E.SYMBOLS.index(sym) + 1] * n for sym, n in comp.items()), 3)
        entry = {
            "version": 1, "id": cid, "name": name, "formula": formula, "formula_display": display(formula), "composition": comp,
            "molar_mass_g_mol": {"value": mass, "unit": "g/mol", "status": "derived",
                                 "source": "sum of abridged standard atomic weights in data/elements/elements.json"},
            "state_at_20c": state, "appearance": look,
            "color_hex": {"value": color, "status": "display"}, "solution_color_hex": None if solution_color is None else {"value": solution_color, "status": "display"},
            "density_g_cm3": v(density, "g/cm3", "gases at 0 degC and 1 atm" if state == "gas" else None),
            "melting_c": v(mp, "degC"), "boiling_c": v(bp, "degC"),
            "solubility_in_water": {"g_per_100ml_at_20c": v(solubility, "g/100 mL"), "note": solubility_note},
            "hazards": {"classes": hazards, "summary": hazard_text, "status": "unverified_reference", "source": SRC},
            "storage": storage,
            "reactions": [{"role": r, "note": t} for r, t in roles],
            "educational_notes": notes,
            "simulation": {"supported": sim is not None, "chemical_id": sim,
                           "note": "Linked to the playable chemical of this id." if sim else "Reference data only; not yet playable in the simulation."},
            "references": [SRC],
        }
        if sim:
            entry["simulation"]["note"] = "Linked to the playable chemical of this id (the playable version may be a dilute solution)."
        (out_dir / f"{cid}.json").write_text(json.dumps(entry, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
    print("wrote", len(C), "compounds")


if __name__ == "__main__":
    main()
